CREATE TABLE IF NOT EXISTS plays (id INTEGER PRIMARY KEY, n INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS recent (k TEXT PRIMARY KEY, t INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ratings (id INTEGER PRIMARY KEY, up INTEGER NOT NULL DEFAULT 0, down INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS votes (k TEXT PRIMARY KEY, v INTEGER NOT NULL, t INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ipcap (k TEXT PRIMARY KEY, n INTEGER NOT NULL, b INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS snap (k TEXT PRIMARY KEY, v TEXT NOT NULL, t INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY, first INTEGER NOT NULL, seen INTEGER NOT NULL, info TEXT NOT NULL DEFAULT '{}', label TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS commands (id INTEGER PRIMARY KEY AUTOINCREMENT, target TEXT NOT NULL, type TEXT NOT NULL, payload TEXT NOT NULL DEFAULT '{}', t INTEGER NOT NULL);
